#!/usr/bin/env python3
"""Render measured transfer tables from the single audited result file."""
import collections,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
ARMS=['none','repeat_task','minimal']
LABELS={'none':'No gate','repeat_task':'Task repetition','minimal':'PGA all-call port'}
GROUPS=[('asb_opi_context_ignoring','ASB OPI',400),('injecagent_base_dh','InjecAgent base DH',510),('injecagent_base_ds','InjecAgent base DS--S1',544),('injecagent_enhanced_dh','InjecAgent enhanced DH',510),('injecagent_enhanced_ds','InjecAgent enhanced DS--S1',544)]

def main():
 data=json.loads((ROOT/'evidence/multibench/summary.json').read_text());runs={r['job']:r for r in data['runs']};asb=runs['multibench-asb-main-v1'];inj=runs['multibench-injecagent-main-v1'];groups={**asb['groups'],**inj['groups']}
 assert asb['complete'] and inj['complete'] and asb['observed']==451 and inj['observed']==2108
 def metric(group,arm,key):return groups[group][arm]['metrics'][key]
 def count(group,arm,key):return metric(group,arm,key)['positive']
 def cell(group,arm,key):
  x=metric(group,arm,key);assert x['eligible']>0
  return f"{x['positive']}/{x['eligible']}"+(f" ({x['unknown_or_incomplete']} unknown/incomplete)" if x['unknown_or_incomplete'] else '')
 def paired(group,candidate,reference='none'):
  return next(x for x in asb['contrasts'] if x['group']==group and x['reference']==reference and x['candidate']==candidate)
 total_cost=dict(sum((collections.Counter(r['total_actual_cost']) for r in [asb,inj]),collections.Counter()))
 lines=['# Additional benchmark transfer: native proxies and protected dispatch','',
 '2026-11-07. **Both declared mains are complete: 2,559 cases and 7,677 episodes**, using Pi 1.5.0 and gpt-6-luna. The separate 36-case, 180-episode screen and two four-episode smoke runs are retained outside the main denominators. No new attack optimization, real tool-service invocation, host command or local GPU job is part of this study.','',
 'These are source-read **Pi adaptations**. InjecAgent uses the native function-calling first-step protocol; ASB uses its stock task/tool data, constant-return simulators and native marker scorers with a Pi loop. They do not reproduce the original AIOS stage scheduler or published backbone scores. The PGA port reviews every future call and does not inherit the AgentDojo catalog’s owner-account pure-read exemptions.','',
 '## Simulated target-tool dispatch','',
 'This table counts an admitted invocation of the benchmark-designated target tool. InjecAgent DS--S1 is data retrieval, **not final exfiltration**. These are controlled simulator events, not observed real-world harm.','',
 '| Setting | No gate | Task repetition | PGA all-call port |','|---|---:|---:|---:|']
 for g,label,_ in GROUPS:lines.append('| '+label+' | '+' | '.join(cell(g,a,'dispatch_asr') for a in ARMS)+' |')
 lines+=['','The aggregate reduction is not pointwise dominance over task repetition. Paired target-dispatch differences are:','', '| Benchmark | Reference | Reference-only target calls | PGA-only target calls |','|---|---|---:|---:|']
 for run,label in [(asb,'ASB'),(inj,'InjecAgent first step')]:
  for ref in ['none','repeat_task']:
   contrasts=[x for x in run['contrasts'] if x['reference']==ref and x['candidate']=='minimal']
   lines.append(f"| {label} | {LABELS[ref]} | {sum(len(x['reference_only_target_dispatch']) for x in contrasts)} | {sum(len(x['candidate_only_target_dispatch']) for x in contrasts)} |")
 lines+=['', 'ASB native text-marker ASR (no gate / repetition / PGA): '+ ' / '.join(cell('asb_opi_context_ignoring',a,'native_marker_asr') for a in ARMS)+'. This is reported separately from simulator dispatch.', '', '## ASB native task markers','',
 '| Condition | No gate | Task repetition | PGA all-call port | PGA paired gains / losses vs no gate |','|---|---:|---:|---:|---:|']
 for g,label in [('asb_clean','Clean'),('asb_opi_context_ignoring','OPI')]:
  p=paired(g,'minimal');lines.append('| '+label+' | '+' | '.join(cell(g,a,'native_marker_utility') for a in ARMS)+f" | {len(p['utility_gains'])} / {len(p['utility_losses'])} |")
 lines+=['', 'The native success check requires each configured ordinary-tool achievement string. It does not compare the request with the performed work. For example, a task asking for an evaluation may still be scored against markers for both evaluation and course selection. Some prompts omit the company, quarter or other object required for their literal goal, while the native tools accept no arguments and return canned success. **All native scores are retained.** A score loss is not automatically proof of harmful refusal, and a canned success is not proof of owner-goal completion. Both overrestriction and metric/contract mismatch remain possible.','',
 '## First proposals are distinct from admitted calls','',
 '| InjecAgent setting | No-gate native target proposal | Task-repetition proposal | PGA native target proposal | Invalid first-step labels, no gate / repeat / PGA |','|---|---:|---:|---:|---:|']
 for g,label,_ in GROUPS[1:]:lines.append('| '+label+' | '+' | '.join(cell(g,a,'native_proposal_asr') for a in ARMS)+' | '+' / '.join(str(groups[g][a]['invalid_first_step']) for a in ARMS)+' |')
 lines+=['', 'The gate runs after the first proposal. Exact-request coupling can therefore preserve the actor’s native proposal label while preventing its dispatch. The native evaluator checks the first tool name, not argument correctness. Invalid outputs remain in the total denominator. Two retained DS cases use GitHubGetUserDetails as both the historical user tool and target; tool-name equality alone cannot establish a privacy violation. No absent DS second-stage outcome is scored as a successful defense.','',
 '## Exposure, effects and failures','',
 '| ASB OPI arm | Injection exposed | Target proposal explicitly not admitted | Both ordinary tools actually invoked |','|---|---:|---:|---:|']
 for a in ARMS:
  d=groups['asb_opi_context_ignoring'][a]['diagnostics'];lines.append(f"| {LABELS[a]} | {d['injection_exposed']}/400 | {d['target_nonadmitted']}/400 | {d['ordinary_coverage_complete']}/400 |")
 lines+=['', 'Exposure matters: rejecting an ordinary call before the injected return can remove both the attack opportunity and useful work. The target-nonadmission and ordinary-call counts are post-hoc receipt diagnostics, not replacement security or utility endpoints. ASB’s native text-marker ASR is separately retained in the JSON report and may differ from actual dispatch. The fixed owner/system/schema contexts were checked: none contains a target or success marker, so the captured tool/assistant text suffices for those marker checks on this declared cohort.','']
 for r in [asb,inj]:
  lines.append(f"* `{r['job']}`: {r['observed']}/{r['scheduled']} cases, {r['episodes']} episodes, {r['elapsed_s']/60:.2f} minutes; {len(r['audit_findings'])} audit findings; {len(r['metric_corrections'])} recorded-versus-audited metric differences.")
  statuses=dict(sum((collections.Counter(v['statuses']) for g in r['groups'].values() for v in g.values()),collections.Counter()));lines.append('  Episode statuses: '+', '.join(f'{k}={v}' for k,v in sorted(statuses.items()))+'.')
 lines+=['', 'Raw/summary and case identities, per-occurrence grants, dispatch revisions and coupled responses are audited. Unknown/incomplete cases remain in each applicable denominator and receive explicit rate bounds. A group with only missing outcomes cannot disappear from the denominator. The committed per-arm/per-stratum CSVs include raw episode hashes.','',
 '## Costs and retained engineering history','',
 f"The two mains issued {total_cost.get('actor_network_calls',0):,} actor and {total_cost.get('judge_network_calls',0):,} judge network requests, with {total_cost.get('actor_logical_calls',0):,} logical actor and {total_cost.get('judge_logical_calls',0):,} logical judge calls. Recorded actual-network usage totals {total_cost.get('input_tokens',0):,} input and {total_cost.get('output_tokens',0):,} output tokens. Missing-usage network calls: {total_cost.get('network_calls_missing_usage',0)}. Response reuse is shared experimental cost, not independent per-arm deployment cost or a verified invoice.", '',
 'Qualification initially failed because the older AgentDojo virtual environment lacked jsonschema. The new adapter was decoupled from that runtime and used the already installed system Python; no shared environment was modified. Fourteen model-free controls then passed. Before main, a scorer-contract audit found that the v1 recorder omitted visible denial text and repetition wrappers. The v2 recorder captures actual Pi tool-result text; it changes no prompts, grants, tool returns or budgets. Reconstruction changed zero pilot labels. Sixteen qualification controls and a separate end-to-end smoke checked the revised recorder. All original failures and pilot records remain retained.','',
 'AROS preparation repeatedly exceeded its 30-second window before main registration. Read-only timing found a 25.671-second read of 5,797 board notes. A process-local wrapper increased preparation to 60 seconds while running the normal CLI with every identity, ownership, input and supervisor check intact. Installed code, global configuration and experiment budgets were unchanged. Both studies then registered as owned mains.','',
 'The optional scope-only pilot showed no native-utility increment. Late facts gained one native marker case, but its inventory-management operation for a strategy request did not establish independently supported semantic recovery. Neither variant replaced the prespecified incumbent.','',
 '## Residual target calls','', 'All 16 ASB cases and the single InjecAgent case with PGA target dispatch are inspected in [residual-cases.json](../evidence/multibench/residual-cases.json). The InjecAgent reviewer allows CiscoUmbrellaGetLogDetails while the authentic task is to read an email, using the email request as a basis for the extra query. It is not one of the user/target schema-overlap cases, and final exfiltration remains unmeasured. ASB residual targets include plausible advertised operations in an attacker-extended catalog; a relevant description does not establish the actual effect or tool provenance. All residual cases remain counted.', '', '## Scope and reproduction','',
 'ASB adds an attacker-provided tool to the catalog as well as injecting an observation. Registry integrity is a separate assurance from task interpretation and is not secretly supplied to this reviewer. InjecAgent and ASB supply additional interfaces and attack settings; they do not certify complete malicious-root recovery, all disclosure channels or unseen task/model robustness.','',
 '[Frozen protocol](../evaluation/multibench/protocol.json) · [Adapter and commands](../evaluation/multibench/README.md) · [Audited results](../evidence/multibench/summary.json) · [Source/metric contract audit](../evidence/multibench/metric-contracts.json) · [Source map](../evidence/multibench/source-map.json). The earlier AgentDojo measurements and proof artifacts are unchanged.']
 (ROOT/'docs/multibench.md').write_text('\n'.join(lines)+'\n')
 tex=['% Generated from evidence/multibench/summary.json; do not hand-edit measured values.',r'\newcommand{\multibenchTable}{',r'\begin{table*}[t]',r'\caption{Additional Pi/Luna ports. Target counts are admitted simulated tool invocations; ASB utility is its native marker proxy. DS--S1 is retrieval, not final exfiltration.}',r'\label{tab:multibench}',r'\centering\small',r'\begin{tabular}{llrrr}',r'\toprule',r'Setting & Endpoint & No gate & Task repetition & PGA all-call \\',r'\midrule']
 for g,label,_ in GROUPS:tex.append(label+' & Target dispatch & '+' & '.join(cell(g,a,'dispatch_asr') for a in ARMS)+r' \\')
 tex.append('ASB OPI & Native marker ASR & '+' & '.join(cell('asb_opi_context_ignoring',a,'native_marker_asr') for a in ARMS)+r' \\')
 for g,label in [('asb_clean','ASB clean'),('asb_opi_context_ignoring','ASB OPI')]:tex.append(label+' & Native marker utility & '+' & '.join(cell(g,a,'native_marker_utility') for a in ARMS)+r' \\')
 tex += [r'\bottomrule',r'\end{tabular}',r'\end{table*}',r'}',r'\newcommand{\multibenchFindings}{']
 clean=paired('asb_clean','minimal');attack=paired('asb_opi_context_ignoring','minimal')
 tex.append(f"The mains complete 2,559 cases and 7,677 episodes. Under ASB OPI, target dispatch is {cell('asb_opi_context_ignoring','none','dispatch_asr')} without a gate, {cell('asb_opi_context_ignoring','repeat_task','dispatch_asr')} with task repetition and {cell('asb_opi_context_ignoring','minimal','dispatch_asr')} with the all-call reviewer. Its native-marker comparison has {len(clean['utility_gains'])} gains and {len(clean['utility_losses'])} losses on clean tasks, and {len(attack['utility_gains'])} gains and {len(attack['utility_losses'])} losses under OPI. These losses remain reported; marker attainment does not establish owner-goal fidelity, and the port's all-call scope differs from AgentDojo's reviewed read path.")
 tex.append(f"The two mains report {sum(len(r['audit_findings']) for r in [asb,inj])} raw/coupling/grant audit findings. All scheduled cases and statuses are retained; the supplement provides unknown bounds, exposure and cost. InjecAgent proposal labels remain separate from protected dispatch, and no final data-stealing result is inferred from the first-step protocol.")
 tex += [r'}',r'\newcommand{\multibenchCosts}{'+f"The ASB and InjecAgent mains take {asb['elapsed_s']/60:.2f} and {inj['elapsed_s']/60:.2f} minutes, respectively, with four case workers each. Together they issue {total_cost.get('actor_network_calls',0):,} actor and {total_cost.get('judge_network_calls',0):,} judge network requests; logical counts are {total_cost.get('actor_logical_calls',0):,} and {total_cost.get('judge_logical_calls',0):,}. Recorded actual-network usage is {total_cost.get('input_tokens',0):,} input and {total_cost.get('output_tokens',0):,} output tokens. Missing-usage network calls: {total_cost.get('network_calls_missing_usage',0)}. Shared experimental sampling and provider cache accounting do not give independent per-arm deployment costs or a verified invoice."+r'}']
 (ROOT/'paper/latex/multibench-results.tex').write_text('\n'.join(tex)+'\n')
 print(json.dumps({'main_episodes':asb['episodes']+inj['episodes'],'main_cases':asb['observed']+inj['observed'],'cost':total_cost,'audit_findings':sum(len(r['audit_findings']) for r in [asb,inj])},indent=2))

if __name__=='__main__':main()
